Generate a standalone C reproducer that triggers this vulnerability:

File: arm/palette_neon_intrinsics.c
Line: 74
Function: png_target_do_expand_palette_rgba8_neon
Bug type: out-of-bounds-write
CWE: CWE-787
Explanation: The loop at line 65 processes 4 pixels per iteration but uses the condition i < row_width. When row_width is not a multiple of 4 and >=5, the last iteration still executes with fewer than 4 pixels remaining, causing dp to point before the start of the destination row and vst1q_u32 to write 16 bytes out of bounds.

Source context:
```c
       34:       uint8x16x3_t v = vld3q_u8((const png_byte *)(palette + i));
       35:       w.val[0] = v.val[0];
       36:       w.val[1] = v.val[1];
       37:       w.val[2] = v.val[2];
       38:       vst4q_u8(riffled_palette + (i << 2), w);
       39:    }
       40: 
       41:    /* Fix up the missing transparency values. */
       42:    for (i = 0; i < num_trans; i++)
       43:       riffled_palette[(i << 2) + 3] = trans_alpha[i];
       44: }
       45: 
       46: /* Expands a palettized row into RGBA8. */
       47: static png_uint_32
       48: png_target_do_expand_palette_rgba8_neon(const png_uint_32 *riffled_palette,
       49:     png_uint_32 row_width, const png_byte **ssp, png_byte **ddp)
       50: {
       51:    const png_uint_32 pixels_per_chunk = 4;
       52:    png_uint_32 i;
       53: 
       54:    png_debug(1, "in png_do_expand_palette_rgba8_neon");
       55: 
       56:    if (row_width < pixels_per_chunk)
       57:       return 0;
       58: 
       59:    /* This function originally gets the last byte of the output row.
       60:     * The NEON part writes forward from a given position, so we have
       61:     * to seek this back by 4 pixels x 4 bytes.
       62:     */
       63:    *ddp = *ddp - ((pixels_per_chunk * sizeof(png_uint_32)) - 1);
       64: 
       65:    for (i = 0; i < row_width; i += pixels_per_chunk)
       66:    {
       67:       uint32x4_t cur;
       68:       const png_byte *sp = *ssp - i;
       69:       png_byte *dp = *ddp - (i << 2);
       70:       cur = vld1q_dup_u32 (riffled_palette + *(sp - 3));
       71:       cur = vld1q_lane_u32(riffled_palette + *(sp - 2), cur, 1);
       72:       cur = vld1q_lane_u32(riffled_palette + *(sp - 1), cur, 2);
       73:       cur = vld1q_lane_u32(riffled_palette + *(sp - 0), cur, 3);
>>>    74:       vst1q_u32((void *)dp, cur);
       75:    }
       76:    if (i != row_width)
       77:    {
       78:       /* Remove the amount that wasn't processed. */
       79:       i -= pixels_per_chunk;
       80:    }
       81: 
       82:    /* Decrement output pointers. */
       83:    *ssp = *ssp - i;
       84:    *ddp = *ddp - (i << 2);
       85:    return i;
       86: }
       87: 
       88: /* Expands a palettized row into RGB8. */
       89: static png_uint_32
       90: png_target_do_expand_palette_rgb8_neon(const png_color *paletteIn,
       91:     png_uint_32 row_width, const png_byte **ssp, png_byte **ddp)
       92: {
       93:    /* TODO: This case is VERY dangerous: */
       94:    const png_byte *palette = (const png_byte *)paletteIn;
       95: 
       96:    const png_uint_32 pixels_per_chunk = 8;
       97:    png_uint_32 i;
       98: 
       99:    png_debug(1, "in png_do_expand_palette_rgb8_neon");
      100: 
      101:    if (row_width <= pixels_per_chunk)
      102:       return 0;
      103: 
      104:    /* Seeking this back by 8 pixels x 3 bytes. */
      105:    *ddp = *ddp - ((pixels_per_chunk * sizeof(png_color)) - 1);
      106: 
      107:    for (i = 0; i < row_width; i += pixels_per_chunk)
      108:    {
      109:       uint8x8x3_t cur;
      110:       const png_byte *sp = *ssp - i;
      111:       png_byte *dp = *ddp - ((i << 1) + i);
      112:       cur = vld3_dup_u8(palette + sizeof(png_color) * (*(sp - 7)));
      113:       cur = vld3_lane_u8(palette + sizeof(png_color) * (*(sp - 6)), cur, 1);
      114:       cur = vld3_lane_u8(palette + sizeof(png_color) * (*(sp - 5)), cur, 2);
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libpng_upstream reproducer.c -L/tmp/libpng_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libpng_upstream
